def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def normalize_email(value):
        value = value.strip()
        if "<" in value and ">" in value:
            start = value.find("<")
            end = value.find(">", start + 1)
            if end != -1:
                value = value[start + 1:end]

        value = value.strip().lower()
        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        match = re.search(r"x|ext|#", value, re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def parse_updated(value):
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        prepared.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": row["source"].strip().lower(),
            "tags": row["tags"],
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
            "updated_dt": updated,
        })

    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        last_key = row["last_name"].lower()
        if row["phone"] and last_key:
            key = (row["phone"], last_key)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def pick_field(group, field, valid_only=False):
        candidates = [
            row for row in group
            if row[field] and (not valid_only or row[field])
        ]
        if not candidates:
            return ""
        best = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated_dt"].timestamp(),
                row["index"],
            ),
        )
        return best[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(r["index"] for r in group))

    for group in ordered_groups:
        latest = max(row["updated_dt"] for row in group)
        tags = sorted({
            tag.strip().lower()
            for row in group
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        })

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email", valid_only=True),
            "phone": pick_field(group, "phone", valid_only=True),
            "source": pick_field(group, "source"),
            "tags": ";".join(tags),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
